/* ════════════════════════════════════════════════════════════════════════════
   SITAM SPACE v25 — real events sent by the user (2026-11-03), posters in public/events/
   • Posters may now also be a file of the site itself ("/events/…"), not only an https:// link.
   • SDU events: JANA TALKS (4 Nov), Research Poster Day (13 Nov; time 10:00 and room TBA until known),
     past: Darkhonbek Mamataliev talk (7 Sep). Outside SDU / competitions: QazTech Meetup "Tech Talqy" (3 Nov),
     Wemathify (4 Nov, at SDU), DATA CHALLENGE '26 (7–8 Nov, Astana). External kind "other" = Industry on the Events page.
   Written as plain statements (one per event) so it runs the same in every SQL editor. Safe to run more than once.
   ════════════════════════════════════════════════════════════════════════════ */

alter table public.events drop constraint if exists events_poster_url_check;
alter table public.events drop constraint if exists events_poster_url_check1;
alter table public.events add constraint events_poster_url_check check (poster_url is null or poster_url ~* '^(https?://|/events/)');
alter table public.external_events drop constraint if exists external_events_poster_url_check;
alter table public.external_events drop constraint if exists external_events_poster_url_check1;
alter table public.external_events add constraint external_events_poster_url_check check (poster_url is null or poster_url ~* '^(https?://|/events/)');

insert into public.events (kind, title, description, starts_at, room, speaker, speaker_role, tags, poster_url)
select 'industrial'::public.event_kind, 'JANA TALKS: «XXI ғасыр көшбасшысы»', 'JANA TALKS is a new format at SDU University that brings experts from different fields and students together. The first guest is the Rector of SDU University, Arman Zhumazhanov: an open talk about leadership, education, growth and the future. Students can ask their own questions. 17:00–20:00, Blue Hall (304-305), SDU Life Centre.', '2026-11-04 17:00:00+05'::timestamptz, 'Blue Hall (304-305), SDU Life Centre', 'Arman Zhumazhanov', 'Rector of SDU University', array['Leadership', 'Talk', 'Q&A']::text[], '/events/jana-talks.jpg'
 where not exists (select 1 from public.events where lower(title) = lower('JANA TALKS: «XXI ғасыр көшбасшысы»') and starts_at::date = ('2026-11-04 17:00:00+05'::timestamptz)::date);
insert into public.events (kind, title, description, starts_at, room, speaker, speaker_role, tags, poster_url)
select 'research'::public.event_kind, 'Research Poster Day', 'Have an idea you are curious about? Turn it into a project and share it with the SDU community. Open to all SDU students; no research experience or finished study is required, beginners are welcome. You can present research proposals, ongoing or completed research, practical projects, literature reviews and analytical studies, on any topic. Individually or in teams of up to 3, in English, Kazakh or Russian. Format: A1 poster + 3-minute presentation. Awards: EDU / SSBL / SITAM School Choice Award, Best Poster Design, Best Research Innovation, People''s Choice Award. Every participant gets a Certificate of Participation. Registration is open. The time and room will be announced.', '2026-11-13 10:00:00+05'::timestamptz, 'TBA', null, null, array['Research', 'Posters', 'Students']::text[], '/events/research-poster-day.jpg'
 where not exists (select 1 from public.events where lower(title) = lower('Research Poster Day') and starts_at::date = ('2026-11-13 10:00:00+05'::timestamptz)::date);
insert into public.events (kind, title, description, starts_at, room, speaker, speaker_role, tags, poster_url)
select 'industrial'::public.event_kind, 'How to Build a Global IT Career & Crack Tech Interviews', 'Our first event of the semester. Darkhonbek Mamataliev, Senior iOS Engineer at Roblox (ex-TikTok, ex-Uber), shares his experience from Roblox, TikTok and Uber: FAANG resumes, tech interview strategies and a live Q&A. 10:30–11:30, SDU Campus, room I201.', '2026-09-07 10:30:00+05'::timestamptz, 'I201', 'Darkhonbek Mamataliev', 'Senior iOS Engineer at Roblox (ex-TikTok, ex-Uber)', array['Career', 'Interviews', 'iOS']::text[], '/events/darkhonbek-mamataliev.jpg'
 where not exists (select 1 from public.events where lower(title) = lower('How to Build a Global IT Career & Crack Tech Interviews') and starts_at::date = ('2026-09-07 10:30:00+05'::timestamptz)::date);
insert into public.external_events (kind, title, organizer, location, url, starts_on, ends_on, year, description, location_type, cohosted, poster_url)
select 'other', 'QazTech Meetup: Tech Talqy with Narikbi Maksut', 'QazTech Meetup · Activat VC', 'Choco office, Almaty Towers, Baizakov St. 280, Almaty (separate entrance)', 'https://luma.com/15je1k26', '2026-11-03'::date, '2026-11-03'::date, 2026, 'Speaker: Narikbi Maksut, iOS developer at Booking.com and author of the Narikbi LIVE podcast. His path started on the ballet stage and led to a global IT company. 2014–2019: iOS developer at iBEC Systems, Crystal Spring, Bugin Group, DAR Ecosystem and Toptal. Since 2019 at Booking.com in Amsterdam. Forbes Kazakhstan "30 under 30" (2022). Narikbi LIVE (since 2020) is a Kazakh-language podcast about professional and personal growth. 17:00. Free entry, registration on Luma. Partner: Freedom.', 'outside', false, '/events/qaztech-tech-talqy.jpg'
 where not exists (select 1 from public.external_events where lower(title) = lower('QazTech Meetup: Tech Talqy with Narikbi Maksut'));
insert into public.external_events (kind, title, organizer, location, url, starts_on, ends_on, year, description, location_type, cohosted, poster_url)
select 'olympiad', 'Wemathify — math tournament', 'WE · SITAM', 'SDU, block I, room I301', 'https://docs.google.com/forms/d/e/1FAIpQLSd5A_7sJT9VIGJM4RLBhX_eJ_llbE83dxkC3AHq2iOOvcwBAQ/viewform', '2026-11-04'::date, '2026-11-04'::date, 2026, 'A math tournament from simple logic tasks to real olympiad-level problems. 17:30, room I301. Prize pool: 1st place 40 000 ₸, 2nd 30 000 ₸, 3rd 20 000 ₸. Teams of 4; any SITAM student of any year can take part. A refundable deposit of 1 000 ₸ per team confirms participation (it is not returned if the team does not come). The team captain fills in the Google form.', 'sdu', false, '/events/wemathify.jpg'
 where not exists (select 1 from public.external_events where lower(title) = lower('Wemathify — math tournament'));
insert into public.external_events (kind, title, organizer, location, url, starts_on, ends_on, year, description, location_type, cohosted, poster_url)
select 'hackathon', 'DATA CHALLENGE ''26', 'DataSci · NU ADSL · NU Impact Foundation · Freedom', 'Nazarbayev University, Astana', 'https://datachallenge.datasci.website/', '2026-11-07'::date, '2026-11-08'::date, 2026, 'Work on a real-world case from the sponsor Freedom Broker and compete for a 1 000 000 ₸ prize pool. Teams of 2 to 4. Offline at Nazarbayev University, Astana. Registration deadline: November 5, 23:59. Free entry, open to all SDU students. Thanks to NU ADSL for the sponsorship and NU Impact Foundation for the support.', 'outside', false, '/events/data-challenge-26.jpg'
 where not exists (select 1 from public.external_events where lower(title) = lower('DATA CHALLENGE ''26'));
update public.events set poster_url = '/events/jana-talks.jpg' where title ilike 'JANA TALKS%' and poster_url is null;
update public.events set poster_url = '/events/research-poster-day.jpg' where title ilike 'Research Poster Day%' and poster_url is null;
update public.events set poster_url = '/events/darkhonbek-mamataliev.jpg' where title ilike 'How to Build a Global IT Career%' and poster_url is null;
